const allRecords = $("Compute Corrective Deadline").all().map(function (item) { return item.json; });
const totalLocations = allRecords.length;
const criticalCount = allRecords.filter(function (r) { return r.severity === "critical"; }).length;
const majorCount = allRecords.filter(function (r) { return r.severity === "major"; }).length;
const minorCount = allRecords.filter(function (r) { return r.severity === "minor"; }).length;
const pctWithViolation = totalLocations > 0 ? 100 : 0;
// Regional risk score: weighted formula — critical violations weigh heaviest, then major, then minor,
// plus a prevalence component so a franchise with widespread minor issues also trends upward.
const riskScore = Math.round((criticalCount * 25) + (majorCount * 8) + (minorCount * 2) + (pctWithViolation * 0.5));
const CRITICAL_COUNT_THRESHOLD = 2;
const RISK_SCORE_THRESHOLD = 40;
const escalate = (criticalCount >= CRITICAL_COUNT_THRESHOLD) || (riskScore >= RISK_SCORE_THRESHOLD);
const regionSet = {};
allRecords.forEach(function (r) { regionSet[r.region] = true; });
const regionsAffected = Object.keys(regionSet);
const criticalLocations = allRecords.filter(function (r) { return r.severity === "critical"; }).map(function (r) { return r.location_name + " (" + r.location_id + ")"; });
return [{
  json: {
    run_date: new Date().toISOString().slice(0, 10),
    total_locations: totalLocations,
    critical_count: criticalCount,
    major_count: majorCount,
    minor_count: minorCount,
    pct_locations_with_violation: pctWithViolation,
    risk_score: riskScore,
    escalation_threshold: RISK_SCORE_THRESHOLD,
    critical_threshold: CRITICAL_COUNT_THRESHOLD,
    escalate: escalate,
    regions_affected: regionsAffected.join(", "),
    critical_locations_summary: criticalLocations.length > 0 ? criticalLocations.join("; ") : "None",
    records: allRecords
  }
}];

const severityRaw = $input.item.json.severity;
const severity = (typeof severityRaw === "string" ? severityRaw.toLowerCase().trim() : "minor");
const normalizedSeverity = ["critical", "major", "minor"].indexOf(severity) === -1 ? "minor" : severity;
// Real health-code re-inspection windows: critical=10 days, major=30 days, minor=90 days
const REINSPECTION_WINDOWS = { critical: 10, major: 30, minor: 90 };
const windowDays = REINSPECTION_WINDOWS[normalizedSeverity];
const shapeRecord = $("Shape Inspection Record").item.json;
const inspectionDateStr = shapeRecord.inspection_date;
const inspectionDate = inspectionDateStr ? new Date(inspectionDateStr + "T00:00:00Z") : new Date();
const deadline = new Date(inspectionDate.getTime());
deadline.setUTCDate(deadline.getUTCDate() + windowDays);
const deadlineIso = deadline.toISOString().slice(0, 10);
return {
  json: {
    location_id: shapeRecord.location_id,
    location_name: shapeRecord.location_name,
    region: shapeRecord.region,
    inspection_date: shapeRecord.inspection_date,
    violation_category: $input.item.json.violation_category,
    severity: normalizedSeverity,
    code_section: $input.item.json.code_section,
    recommended_corrective_action: $input.item.json.recommended_corrective_action,
    reinspection_window_days: windowDays,
    corrective_deadline: deadlineIso,
    is_critical: normalizedSeverity === "critical"
  }
};
